// Tests for B3 — halftone / textured background classification.
//
// Exercises BgColorDetector::classifyRegion() against the synthetic
// fixtures generated by tests/fixtures/image_pdf/gen_fixtures.py.
// Each test loads one fixture, renders the first page to a QImage at
// the fixture's native DPI, and asserts the classifier returns the
// expected category.
//
// The halftone fixtures are available at TWO DPIs (200 and 600) so
// the test directly proves that the variance-kernel sizing is
// DPI-aware. A classifier tuned for one DPI silently misclassifies
// the other; both fixtures must succeed.
//
// Skips gracefully when fixtures are not generated (they are
// gitignored — run python tests/fixtures/image_pdf/gen_fixtures.py).
//
// See docs/image-pdf-risks.md (B3).

#include <gtest/gtest.h>

#include "tre/BgColorDetector.h"
#include "tre/TreTypes.h"
#include "core/Document.h"
#include "core/MuPdfContext.h"
#include "core/Page.h"

#include <QImage>
#include <filesystem>
#include <memory>
#include <string>

using namespace pdfe::tre;
using namespace pdfe::core;

namespace {

std::string fixtureDir() {
    return std::string(TEST_FIXTURES_DIR) + "/image_pdf/";
}

bool fixtureExists(const char* name) {
    return std::filesystem::exists(fixtureDir() + name);
}

// Render the first page of a fixture at the supplied DPI. Returns a
// null QImage on failure. Uses MuPDF directly via Page::render() at
// (dpi/72) scale, matching the TRE pipeline's rendering math.
QImage renderFixturePage(const char* filename, int dpi) {
    auto ctx = std::make_shared<MuPdfContext>();
    std::unique_ptr<Document> doc;
    try {
        doc = Document::open(ctx, fixtureDir() + filename);
    } catch (...) {
        return {};
    }
    if (!doc || doc->pageCount() == 0) return {};
    auto page = doc->page(0);
    if (!page) return {};
    QRectF bbox = page->boundingBox();
    if (bbox.isEmpty()) return {};
    float scale = static_cast<float>(dpi) / 72.0f;
    return page->render(bbox, scale);
}

PixelRect fullImageRect(const QImage& img) {
    PixelRect r;
    r.x0 = 0;
    r.y0 = 0;
    r.x1 = img.width() - 1;
    r.y1 = img.height() - 1;
    return r;
}

} // namespace

// -----------------------------------------------------------------------
// Baseline: uniform white must classify as Uniform.
// -----------------------------------------------------------------------

TEST(B3BgClassification, UniformWhite_300dpi) {
    if (!fixtureExists("b3_uniform_white_300dpi.pdf")) {
        GTEST_SKIP() << "b3_uniform_white_300dpi.pdf not generated";
    }
    QImage img = renderFixturePage("b3_uniform_white_300dpi.pdf", 300);
    ASSERT_FALSE(img.isNull());
    auto cls = BgColorDetector::classifyRegion(img, fullImageRect(img), 300);
    // Uniform white — variance near zero.
    EXPECT_LT(cls.localVariance, 0.04f);
    EXPECT_TRUE(cls.classification == BgClassification::Uniform ||
                cls.classification == BgClassification::Gradient)
        << "Got " << static_cast<int>(cls.classification)
        << " variance=" << cls.localVariance;
}

// -----------------------------------------------------------------------
// Yellowed paper — still Uniform despite color shift.
// -----------------------------------------------------------------------

TEST(B3BgClassification, YellowedNews_300dpi) {
    if (!fixtureExists("b3_yellowed_news_300dpi.pdf")) {
        GTEST_SKIP();
    }
    QImage img = renderFixturePage("b3_yellowed_news_300dpi.pdf", 300);
    ASSERT_FALSE(img.isNull());
    auto cls = BgColorDetector::classifyRegion(img, fullImageRect(img), 300);
    EXPECT_LT(cls.localVariance, 0.04f);
    EXPECT_TRUE(cls.classification == BgClassification::Uniform ||
                cls.classification == BgClassification::Gradient);
}

// -----------------------------------------------------------------------
// HALFTONE: the core B3 test — classification must detect the dot
// pattern at both 200 and 600 DPI, proving the kernel is DPI-aware.
// -----------------------------------------------------------------------

TEST(B3BgClassification, Halftone_200dpi_notUniform) {
    if (!fixtureExists("b3_halftone_news_200dpi.pdf")) {
        GTEST_SKIP();
    }
    QImage img = renderFixturePage("b3_halftone_news_200dpi.pdf", 200);
    ASSERT_FALSE(img.isNull());
    auto cls = BgColorDetector::classifyRegion(img, fullImageRect(img), 200);
    // Halftone MUST not be classified as Uniform — that would cause
    // a flat solid-color fill to appear at edit boundaries. It may
    // classify as Halftone (ideal) or Textured (adequate) but never
    // as Uniform.
    EXPECT_NE(cls.classification, BgClassification::Uniform);
    EXPECT_NE(cls.classification, BgClassification::Gradient);
    EXPECT_GT(cls.localVariance, 0.04f)
        << "Halftone pattern must produce variance > uniform threshold";
}

TEST(B3BgClassification, Halftone_600dpi_notUniform) {
    if (!fixtureExists("b3_halftone_news_600dpi.pdf")) {
        GTEST_SKIP();
    }
    QImage img = renderFixturePage("b3_halftone_news_600dpi.pdf", 600);
    ASSERT_FALSE(img.isNull());
    auto cls = BgColorDetector::classifyRegion(img, fullImageRect(img), 600);
    // Same assertion at a 3x higher DPI. If the kernel were not
    // scaled by DPI, the halftone dots at 600 DPI (~7 px) would
    // look like uniform "large smooth bumps" relative to a
    // 3-pixel kernel tuned for 200 DPI. The DPI-aware kernel
    // (sourceDpi / 85 lines per inch) must scale with DPI.
    EXPECT_NE(cls.classification, BgClassification::Uniform);
    EXPECT_NE(cls.classification, BgClassification::Gradient);
    EXPECT_GT(cls.localVariance, 0.04f);
}

// -----------------------------------------------------------------------
// Textured/speckled background — not Uniform, high variance.
// -----------------------------------------------------------------------

TEST(B3BgClassification, TexturedGray_300dpi) {
    if (!fixtureExists("b3_textured_gray_300dpi.pdf")) {
        GTEST_SKIP();
    }
    QImage img = renderFixturePage("b3_textured_gray_300dpi.pdf", 300);
    ASSERT_FALSE(img.isNull());
    auto cls = BgColorDetector::classifyRegion(img, fullImageRect(img), 300);
    EXPECT_NE(cls.classification, BgClassification::Uniform);
    EXPECT_GT(cls.localVariance, 0.04f);
}

// -----------------------------------------------------------------------
// Edge cases.
// -----------------------------------------------------------------------

TEST(B3BgClassification, NullImageReturnsUnknown) {
    QImage empty;
    PixelRect r;
    r.x0 = 0; r.y0 = 0; r.x1 = 100; r.y1 = 100;
    auto cls = BgColorDetector::classifyRegion(empty, r, 300);
    EXPECT_EQ(cls.classification, BgClassification::Unknown);
}

TEST(B3BgClassification, TinyRegionReturnsUnknown) {
    QImage img(500, 500, QImage::Format_RGB32);
    img.fill(Qt::white);
    PixelRect r;
    r.x0 = 0; r.y0 = 0; r.x1 = 5; r.y1 = 5;  // Below 16-px minimum
    auto cls = BgColorDetector::classifyRegion(img, r, 300);
    EXPECT_EQ(cls.classification, BgClassification::Unknown);
}

TEST(B3BgClassification, SolidWhite_300dpi_Uniform) {
    QImage img(1000, 1000, QImage::Format_RGB32);
    img.fill(Qt::white);
    auto cls = BgColorDetector::classifyRegion(img, fullImageRect(img), 300);
    EXPECT_EQ(cls.classification, BgClassification::Uniform);
    EXPECT_LT(cls.localVariance, 0.001f);
}

TEST(B3BgClassification, RandomNoise_Textured) {
    QImage img(500, 500, QImage::Format_RGB32);
    for (int y = 0; y < img.height(); ++y) {
        for (int x = 0; x < img.width(); ++x) {
            int v = (x * 37 + y * 73) % 256;
            img.setPixel(x, y, qRgb(v, v, v));
        }
    }
    auto cls = BgColorDetector::classifyRegion(img, fullImageRect(img), 300);
    EXPECT_NE(cls.classification, BgClassification::Uniform);
    EXPECT_NE(cls.classification, BgClassification::Gradient);
}

// -----------------------------------------------------------------------
// The critical cross-DPI invariant — the classifier must correctly
// identify BOTH halftone fixtures (200 and 600 DPI) as non-uniform.
// A classifier tuned for one DPI silently misclassifies the other;
// this test fails early when that regression happens.
// -----------------------------------------------------------------------

TEST(B3BgClassification, HalftoneClassificationIsDpiAware) {
    const bool have200 = fixtureExists("b3_halftone_news_200dpi.pdf");
    const bool have600 = fixtureExists("b3_halftone_news_600dpi.pdf");
    if (!have200 || !have600) {
        GTEST_SKIP() << "Requires both halftone fixtures";
    }
    QImage img200 = renderFixturePage("b3_halftone_news_200dpi.pdf", 200);
    QImage img600 = renderFixturePage("b3_halftone_news_600dpi.pdf", 600);
    ASSERT_FALSE(img200.isNull());
    ASSERT_FALSE(img600.isNull());

    auto cls200 = BgColorDetector::classifyRegion(
        img200, fullImageRect(img200), 200);
    auto cls600 = BgColorDetector::classifyRegion(
        img600, fullImageRect(img600), 600);

    // Both MUST be non-uniform. This catches any regression to a
    // DPI-insensitive kernel.
    EXPECT_NE(cls200.classification, BgClassification::Uniform);
    EXPECT_NE(cls200.classification, BgClassification::Gradient);
    EXPECT_NE(cls600.classification, BgClassification::Uniform);
    EXPECT_NE(cls600.classification, BgClassification::Gradient);
}
